import type {
    ApiV3DeleteMethods,
    ApiV3GetMethods,
    ApiV3PatchMethods,
    ApiV3PostMethods,
    ApiV3PutMethods,
} from '@weavix/tracker-api-types';

import {
    type TrackerApiCallOptions as BaseCallOptions,
    type TrackerApiInitOptions as BaseInitOptions,
    trackerApi as trackerApiBase,
} from './trackerApiBase';

export type TrackerApiCallOptions = BaseCallOptions;
export type TrackerApiInitOptions = BaseInitOptions;

type ApiResult<M> = {
    [K in keyof M]: M[K] extends (...args: infer A) => Promise<infer R>
        ? (...args: A) => Promise<{ data: R; headers: Record<string, string> }>
        : never;
};

export interface TrackerApiV3 {
    get: ApiResult<ApiV3GetMethods>;
    post: ApiResult<ApiV3PostMethods>;
    put: ApiResult<ApiV3PutMethods>;
    patch: ApiResult<ApiV3PatchMethods>;
    delete: ApiResult<ApiV3DeleteMethods>;
}

export interface TrackerApi {
    v3: TrackerApiV3;
}

export const trackerApi = trackerApiBase as unknown as TrackerApi;
